INSERT INTO `downloads` (`id`, `title`, `category_type`, `file_path`, `file_type`, `file_size`, `download_count`, `created_at`, `updated_at`, `description`, `cover_image`) VALUES
(5, 'Logo Resmi Pondok Pesantren Raudhatul Ulum Sakatiga (High Resolution)', 'Logo', '/uploads/logo-ppru-banner.png', 'PNG', '120 KB', 780, '2026-09-11 15:07:23', '2026-09-11 15:07:23', 'Logo resmi dan emblem Pondok Pesantren Raudhatul Ulum Sakatiga format PNG high resolution transparan.', NULL),
(6, 'Logo Lambang Pondok Pesantren Raudhatul Ulum Square HD', 'Logo', '/uploads/logo-ppru-square.png', 'PNG', '85 KB', 316, '2026-09-11 15:07:23', '2026-09-12 08:33:49', 'Emblem lambang bulat Pondok Pesantren Raudhatul Ulum Sakatiga HD.', NULL),
(19, 'Panduan Mutqin Tahfidz Al-Qur\'an 30 Juz Santri PPRU', 'E-Book', '/uploads/downloads/panduan-mutqin-tahfidz-ppru.pdf', NULL, '9 KB', 295, '2026-09-12 07:42:35', '2026-09-12 08:10:12', 'Modul resmi kurikulum tahfidz mutqin Pondok Pesantren Raudhatul Ulum Sakatiga berbasis sanad dan metode mutqin. Memuat metode ziyadah, jadwal muraja\'ah akbar, target juz kelulusan, dan tata tertib munaqosah terbuka.', '/uploads/covers/cover-tahfidz-mutqin.webp'),
(20, 'Buku Saku Adab & 10 Karakter (Muwashofat) Santri JSIT', 'E-Book', '/uploads/downloads/buku-saku-adab-karakter-santri.pdf', NULL, '6.9 KB', 280, '2026-09-12 07:42:36', '2026-09-12 08:10:12', 'Pedoman pembiasaan akhlak islami, adab kepada guru dan orang tua, tata tertib santri asrama dan sekolah, serta 10 Muwashofat Tarbiyah JSIT Indonesia.', '/uploads/covers/cover-karakter-santri.webp'),
(21, 'Petunjuk Praktikum Laboratorium Sains Terpadu PPRU Sakatiga', 'E-Book', '/uploads/downloads/petunjuk-praktikum-sains-terpadu.pdf', NULL, '6.6 KB', 298, '2026-09-12 07:42:36', '2026-09-12 08:10:12', 'Pedoman eksperimen laboratorium biologi, kimia, dan fisika untuk santri Pondok Pesantren Raudhatul Ulum yang dilengkapi keselamatan kerja lab dan metode analisis ilmiah Kurikulum Merdeka.', '/uploads/covers/cover-praktikum-sains.webp'),
(22, 'Kurikulum Pembinaan Da\'i Muda, Khitabah & Public Speaking', 'E-Book', '/uploads/downloads/kurikulum-pembinaan-dai-muda.pdf', NULL, '6.5 KB', 234, '2026-09-12 07:42:36', '2026-09-12 08:10:12', 'Kumpulan materi public speaking, retorika dakwah 3 bahasa (Indonesia, Arab, Inggris), dan sistematika kultum untuk melatih santri menjadi orator dan pemimpin umat masa depan.', '/uploads/covers/cover-dai-muda.webp'),
(23, 'Buku Saku Kosakata Harian Bilingual Bahasa Arab & Inggris Santri', 'E-Book', '/uploads/downloads/buku-saku-kosakata-bilingual.pdf', NULL, '6.6 KB', 283, '2026-09-12 07:42:36', '2026-09-12 08:10:12', 'Modul percakapan bilingual harian asrama dan lingkungan pesantren untuk mempercepat penguasaan active speaking bahasa Arab dan Inggris bagi santri Pondok Pesantren Raudhatul Ulum.', '/uploads/covers/cover-bilingual-arab-inggris.webp'),
(24, 'Panduan Sukses Seleksi Masuk PTN (SNBP, SNBT & Kedinasan)', 'E-Book', '/uploads/downloads/panduan-sukses-snbt-ptn.pdf', NULL, '6.6 KB', 158, '2026-09-12 07:42:36', '2026-09-12 08:10:12', 'Strategi sukses menembus perguruan tinggi negeri impian, pembedahan materi Tes Potensi Skolastik (TPS), penalaran matematika, literasi bahasa, dan tips memilih prodi realistis.', '/uploads/covers/cover-sukses-snbt.webp');
INSERT INTO `fasilitas` (`id`, `name`, `slug`, `description`, `address`, `phone`, `email`, `website`, `icon`, `thumbnail`, `order`, `created_at`, `updated_at`) VALUES
(1, 'Masjid Baitul Qur\'an & Pusat Ibadah', 'masjid-baitul-quran-pusat-ibadah', 'Masjid representatif sebagai pusat sholat berjamaah lima waktu, halaqah tahfidz Al-Qur\'an, kajian kitab kuning, dan pembinaan ruhiyah santri.', 'pondok Pondok Pesantren Raudhatul Ulum Sakatiga, Ogan Ilir', '0812-7890-1950', 'sekretariat@ppru.ac.id', NULL, NULL, '/uploads/fasilitas-masjid.jpg', 1, '2026-09-14 15:27:46', '2026-09-14 19:09:43'),
(2, 'Kompleks Asrama Santri Putra & Putri', 'kompleks-asrama-santri', 'Gedung asrama bertingkat dengan kamar tidur yang nyaman, ventilasi baik, pengawasan musyrif/musyrifah 24 jam, dan lingkungan asri.', 'pondok Pondok Pesantren Raudhatul Ulum Sakatiga, Ogan Ilir', '0812-7890-1950', 'sekretariat@ppru.ac.id', NULL, NULL, '/uploads/fasilitas-asrama.jpg', 2, '2026-09-14 15:27:46', '2026-09-14 19:09:43'),
(3, 'Laboratorium Komputer, Bahasa & IPA Terpadu', 'laboratorium-komputer-bahasa-ipa', 'Fasilitas praktikum modern dengan perangkat komputer terkoneksi internet cepat, audio lab bahasa, dan peralatan eksperimen sains lengkap.', 'pondok Pondok Pesantren Raudhatul Ulum Sakatiga, Ogan Ilir', '0812-7890-1950', 'sekretariat@ppru.ac.id', NULL, NULL, '/uploads/fasilitas-lab.jpg', 3, '2026-09-14 15:27:46', '2026-09-14 19:09:43'),
(4, 'Perpustakaan & Pusat Sumber Belajar', 'perpustakaan-pusat-sumber-belajar', 'Koleksi ribuan kitab turots klasik, buku teks pendidikan nasional, jurnal ilmiah, e-library digital, dan ruang baca ber-AC.', 'pondok Pondok Pesantren Raudhatul Ulum Sakatiga, Ogan Ilir', '0812-7890-1950', 'sekretariat@ppru.ac.id', NULL, NULL, '/uploads/fasilitas-perpustakaan.jpg', 4, '2026-09-14 15:27:46', '2026-09-14 19:09:43'),
(5, 'Gedung Aula Serbaguna & Pusat Haflah', 'gedung-aula-serbaguna', 'Auditorium utama tempat berlangsungnya acara resmi pesantren seperti Haflah Takhtiman, wisuda, seminar internasional, dan perlombaan.', 'pondok Pondok Pesantren Raudhatul Ulum Sakatiga, Ogan Ilir', '0812-7890-1950', 'sekretariat@ppru.ac.id', NULL, NULL, '/uploads/fasilitas-aula.jpg', 5, '2026-09-14 15:27:46', '2026-09-14 19:09:43'),
(6, 'Klinik Kesehatan Pesantren (Poskestren)', 'klinik-poskestren', 'Layanan rawat jalan dan pertolongan pertama santri dengan tenaga medis perawat dan dokter jaga, serta rujukan ke RSUD.', 'pondok Pondok Pesantren Raudhatul Ulum Sakatiga, Ogan Ilir', '0812-7890-1950', 'sekretariat@ppru.ac.id', NULL, NULL, '/uploads/fasilitas-klinik.jpg', 6, '2026-09-14 15:27:46', '2026-09-14 19:09:43');
