INSERT INTO `pages` (`id`, `title`, `slug`, `excerpt`, `content`, `image`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES
(1, 'Sambutan Mudir Pondok Pesantren Raudhatul Ulum', 'sambutan-kepala-sekolah', NULL, '<h2>Assalamu\'alaikum Warahmatullahi Wabarakatuh</h2><p>Segala puji dan syukur kita panjatkan ke hadirat Allah Subhanahu wa Ta\'ala, yang telah melimpahkan rahmat, taufiq, dan inayah-Nya kepada kita semua. Shalawat dan salam senantiasa tercurahkan kepada junjungan kita Nabi Besar Muhammad Shallallahu \'Alaihi Wasallam, keluarga, sahabat, dan pengikutnya yang setia hingga akhir zaman.</p><p>Pondok Pesantren Raudhatul Ulum Sakatiga sejak didirikannya pada tanggal 1 Agustus 1950, bertekad menjadi benteng pertahanan aqidah umat dan basis kaderisasi generasi terbaik (Khoiru Ummah). Memadukan kurikulum kepesantrenan terpadu (Pondok Modern Gontor), Kementerian Agama, serta kurikulum nasional, santri dibina selama 24 jam dalam lingkungan asrama yang asri, disiplin, dan islami.</p><p>Kami menyambut hangat para orang tua/wali santri dan masyarakat luas yang ingin bermitra bersama kami mendidik putra-putri tercinta menjadi insan yang beraqidah lurus, beribadah benar, berakhlak mulia, berilmu luas, mandiri, dan siap berkhidmat bagi umat dan bangsa.</p><p><strong>Wassalamu\'alaikum Warahmatullahi Wabarakatuh</strong><br><em>Mudir PPRU Sakatiga, KH. Tol\'at Wafa Ahmad, Lc.</em></p>', NULL, NULL, NULL, '2026-09-14 14:05:23', '2026-09-14 14:05:23'),
(2, 'Tentang Pondok Pesantren Raudhatul Ulum Sakatiga', 'tentang-kami', NULL, '<p>Pondok Pesantren Raudhatul Ulum (PPRU) Sakatiga adalah lembaga pendidikan Islam yang dikelola oleh Yayasan Perguruan Islam Raudhatul Ulum Sakatiga (YAPIRUS), berlokasi di Desa Sakatiga, Kecamatan Indralaya, Kabupaten Ogan Ilir, Sumatera Selatan (sekitar 40 km dari Kota Palembang).</p><p>Berdiri di atas lahan lebih dari 60 hektar yang mencakup Kampus A, Kampus B, dan Kampus C, lingkungan PPRU tertata asri, berwawasan lingkungan, dan sangat kondusif bagi tumbuh kembang santri. Pesantren menyelenggarakan pendidikan terpadu mulai dari jenjang anak usia dini (TAKIRU), dasar (MIRU), menengah (MATSARU, MARU, SMPIT, SMAIT), program khusus Tahfidzul Qur\'an Lil Aulad (MATQULARU), hingga perguruan tinggi (STITRU).</p>', NULL, NULL, NULL, '2026-09-14 14:05:23', '2026-09-14 14:05:23'),
(3, 'Visi, Misi, dan 10 Jati Diri Santri', 'visi-dan-misi', NULL, '<h3>VISI</h3><p><em>\"Menjadi basis kaderisasi generasi terbaik (Khoiru Ummah) yang bermanfaat luas dan berdaya saing global.\"</em></p><h3>MISI</h3><ol><li><strong>Ta\'lim:</strong> Menyelenggarakan kegiatan pengajaran secara utuh dan terpadu untuk menyiapkan sumber daya insani yang berwawasan luas dan menguasai ilmu syar\'i serta sains teknologi.</li><li><strong>Tarbiyah:</strong> Menginternalisasi nilai-nilai Islam kepada santri untuk membentuk kepribadian berkarakter mulia, kokoh secara moral, spiritual, dan emosional.</li><li><strong>Dakwah:</strong> Melatih dan membekali santri keterampilan dakwah Islamiyah, kepekaan sosial, serta kesiapan menegakkan amar ma\'ruf nahi munkar di tengah masyarakat.</li></ol><h3>10 JATI DIRI SANTRI (SDI RAUDHATUL ULUM)</h3><ol><li>Beraqidah lurus (Salimul Aqidah)</li><li>Beribadah benar (Shahihul Ibadah)</li><li>Berakhlak mulia (Matinul Khuluq)</li><li>Berdikari / Mandiri (Qadirun \'alal Kasbi)</li><li>Berpengetahuan luas (Mutsaqqoful Fikri)</li><li>Berbadan sehat dan kuat (Qowiyyul Jismi)</li><li>Mampu mengendalikan hawa nafsu (Mujahidun li Nafsihi)</li><li>Berdisiplin tinggi (Munazzhomun fi Syu\'unihi)</li><li>Mampu mengelola waktu (Haritsun \'ala Waqtihi)</li><li>Bermanfaat bagi masyarakat (Nafi\'un li Ghairihi)</li></ol>', NULL, NULL, NULL, '2026-09-14 14:05:23', '2026-09-14 14:05:23'),
(4, 'Sejarah Perkembangan Pondok Pesantren Raudhatul Ulum', 'sejarah', NULL, '<p>Sejarah Pondok Pesantren Raudhatul Ulum Sakatiga terbagi ke dalam tiga fase bersejarah:</p><h4>1. Era Cikal Bakal (1930 - 1950 M)</h4><p>PPRU berakar dari dua madrasah bersejarah di Sakatiga sebelum kemerdekaan RI: Madrasah Al-Falah yang didirikan pada tahun 1930 oleh KH. Bahri bin Bunga (dilanjutkan KH. Abdul Ghanie Bahri) dan Madrasah Al-Shibyan yang dirintis pada tahun 1936 oleh KH. Abd. Rahim Mandung dan KH. Abdullah Kenalim. Desa Sakatiga sejak masa itu telah masyhur dijuluki sebagai \"Mekkah Kecil\" di Sumatera Selatan karena banyaknya ulama asal Sakatiga yang menuntut ilmu di tanah suci Mekkah.</p><h4>2. Era Lanjutan Perjuangan (1950 - 1986 M)</h4><p>Pada 1 Agustus 1950, para tokoh dan ulama Sakatiga bersepakat menghidupkan kembali madrasah dengan mendirikan Sekolah Rakyat Islam (SRI) dan Sekolah Menengah Agama Islam (SMAI), yang kemudian disederhanakan menjadi Perguruan Islam Raudhatul Ulum Sakatiga (PIRUS) di bawah naungan YAPIRUS (Akte Notaris Aminus No. 21.A Tahun 1966).</p><h4>3. Era Modern & Boarding School (1986 - Sekarang)</h4><p>Mulai 8 Agustus 1986 di bawah kepemimpinan Mudir KH. Tol\'at Wafa Ahmad, Lc., diterapkan sistem terpadu antara kurikulum Pondok Modern Darussalam Gontor, Departemen Agama, dan Departemen Pendidikan Nasional dengan asrama penuh (boarding school). Jenjang madrasah aliyah dan tsanawiyah PPRU juga mendapatkan piagam muadalah pengakuan kesetaraan dari Universitas Al-Azhar Kairo Mesir dan Universitas Islam Madinah.</p>', NULL, NULL, NULL, '2026-09-14 14:05:23', '2026-09-14 14:05:23');
INSERT INTO `pengumumen` (`id`, `title`, `slug`, `content`, `file_attachment`, `status`, `featured_image`, `created_at`, `updated_at`) VALUES
(72, 'Pengumuman Hasil Kelulusan Seleksi Santri Baru (PSB) Gelombang 1 T.A. 2026/2027', 'pengumuman-kelulusan-psb-gelombang-1-ppru', '<p>Diumumkan kepada seluruh calon santri dan wali santri bahwa hasil seleksi berkas, tes lisan Al-Qur\'an, dan ujian akademik PSB Gelombang 1 telah resmi diterbitkan. Silakan periksa status kelulusan di portal PSB online dan lakukan daftar ulang sebelum batas waktu yang ditentukan.</p>', NULL, 'publish', '/uploads/ppru-gedung-utama.webp', '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(73, 'Maklumat Libur Hari Raya & Jadwal Kembali Santri ke Pondok Pesantren', 'maklumat-libur-hari-raya-dan-jadwal-kembali-santri-ppru', '<p>Berdasarkan keputusan Rapat Pimpinan Ma\'had, jadwal perpulangan santri dan batas waktu kedatangan kembali ke kampus Raudhatul Ulum telah ditetapkan. Seluruh santri wajib mematuhi ketentuan disiplin kepulangan dan membawa kartu perpulangan bermaterai.</p>', NULL, 'publish', '/uploads/ppru-masjid-agung.webp', '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(74, 'Panduan Tata Cara Pembayaran Syahriah via Virtual Account BSI & Bank Sumsel Babel Syariah', 'panduan-pembayaran-syahriah-virtual-account-ppru', '<p>Untuk memudahkan transaksi wali santri, pembayaran SPP/Syahriah, uang asrama, dan katering santri kini dilayani otomatis 24 jam melalui nomor Virtual Account masing-masing santri via Mobile Banking, ATM, dan transfer antarbank.</p>', NULL, 'publish', '/uploads/ppru-perpustakaan-islam.webp', '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(75, 'Petunjuk Teknis Ujian Nihai (Akhir) Santri KMI & Asesmen Madrasah 2026', 'petunjuk-teknis-ujian-nihai-santri-kmi-ppru', '<p>Panduan lengkap tata tertib, jadwal mata pelajaran tahriri dan syafahi, serta kriteria kelulusan muadalah bagi santri kelas akhir Kulliyatul Mu\'allimin Al-Islamiyyah dan Madrasah Aliyah Raudhatul Ulum.</p>', NULL, 'publish', '/uploads/ppru-wisuda-akbar.webp', '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(76, 'Pengumuman Penetapan Musyrif Asrama & Halaqah Tahfidz Santri Semester Genap', 'penetapan-musyrif-asrama-halaqah-tahfidz-ppru', '<p>Bagian Pengasuhan Santri PPRU mengumumkan daftar wali asrama, pembagian kamar santri, serta nama-nama muhaffizh pembimbing halaqah Al-Qur\'an demi menjaga kedisiplinan dan capaian hafalan santri.</p>', NULL, 'publish', '/uploads/ppru-halaqah-quran.webp', '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(77, 'Edaran Tata Tertib Kunjungan Wali Santri & Protokol Kedisiplinan Ma\'had', 'edaran-tata-tertib-kunjungan-wali-santri-ppru', '<p>Waktu sambang/kunjungan orang tua wali santri dibuka secara tertib setiap hari Ahad pada jam yang ditentukan. Dilarang membawa makanan instan berlebih, gawai/handphone terlarang, serta wajib berbusana muslim/muslimah rapi dan sopan.</p>', NULL, 'publish', '/uploads/ppru-panahan-santri.webp', '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(78, 'Informasi Beasiswa Prestasi Tahfidz 30 Juz & Kader Ulama Kerjasama BAZNAS', 'informasi-beasiswa-prestasi-tahfidz-ppru', '<p>Peluang beasiswa pendidikan penuh bagi santri berprestasi hafizh Qur\'an 30 juz dan anak yatim/dhuafa berprestasi akademik untuk jenjang MTs, MA, SMA IT, dan Institut Agama Islam Nur Raudhatul Ulum.</p>', NULL, 'publish', '/uploads/ppru-debat.webp', '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(79, 'Jadwal Layanan Pos Kesehatan Pesantren (Poskestren) & Vaksinasi Santri', 'jadwal-layanan-kesehatan-poskestren-ppru', '<p>Pusat Pelayanan Kesehatan Santri PPRU bekerjasama dengan Dinas Kesehatan dan Rumah Sakit Mitra membuka layanan pemeriksaan kesehatan berkala, dokter spesialis, serta klinik gigi santri setiap pekan.</p>', NULL, 'publish', '/uploads/ppru-robotika-sains.webp', '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(80, 'Pemberitahuan Pendaftaran Ekstrakurikuler Wajib & Pilihan Santri Baru', 'pendaftaran-ekstrakurikuler-santri-ppru', '<p>Daftar pilihan kegiatan minat bakat santri: Kepanduan Pramuka (wajib), Tapak Suci / Pencak Silat, Panahan Tradisional, Karya Ilmiah Remaja, Robotika, Kaligrafi, Muhadharah 3 Bahasa, Jurnalistik, dan Hadroh Marawis.</p>', NULL, 'publish', '/uploads/ppru-pencak-silat.webp', '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(81, 'Jadwal Pendaftaran Ulang & Pembagian Perlengkapan Santri Baru T.A. 2026/2027', 'jadwal-daftar-ulang-perlengkapan-santri-baru-ppru', '<p>Wali santri yang telah dinyatakan lulus seleksi diwajibkan melakukan konfirmasi ukuran seragam pondok, lemari asrama, kasur santri, dan kitab-kitab kurikulum di bagian inventaris Koperasi Pesantren PPRU.</p>', NULL, 'publish', '/uploads/ppru-sarasehan.webp', '2026-09-14 16:40:24', '2026-09-14 16:40:24');
