(394, 'Setoran Hafalan 30 Juz Riwayat Hafsh', 'setoran-hafalan-30-juz-riwayat-hafsh', '<p>Selamat dan sukses atas raihan Setoran Hafalan 30 Juz Riwayat Hafsh oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.</p>', 'Selamat dan sukses atas raihan Setoran Hafalan 30 Juz Riwayat Hafsh oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 'prestasi', '/uploads/2025/04/feed-ig-smait-20250326-132427-0000.webp', '0', 4, '2025-04-08 13:38:33', 'Prestasi: Setoran Hafalan 30 Juz Riwayat Hafsh - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Selamat dan sukses atas raihan Setoran Hafalan 30 Juz Riwayat Hafsh oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-12 07:03:22', '2026-09-14 15:01:37'),
(395, 'Beasiswa Hafizah Hafizh Pendidikan Kedokteran UII Yogyakarta', 'beasiswa-hafizah-hafizh-pendidikan-kedokteran-uii-yogyakarta', '<p>Selamat dan sukses atas raihan Beasiswa Hafizah Hafizh Pendidikan Kedokteran UII Yogyakarta oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.</p>', 'Selamat dan sukses atas raihan Beasiswa Hafizah Hafizh Pendidikan Kedokteran UII Yogyakarta oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 'prestasi', '/uploads/ppru-tahfidz.webp', '0', 4, '2025-04-08 13:43:55', 'Prestasi: Beasiswa Hafizah Hafizh Pendidikan Kedokteran UII Yogyakarta - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Selamat dan sukses atas raihan Beasiswa Hafizah Hafizh Pendidikan Kedokteran UII Yogyakarta oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-12 07:03:22', '2026-09-14 15:01:37'),
(396, 'Tsabitah Aulia meraih Juara 3 Tingkat Provinsi Hifdzil Qur\'an', 3823, '<p>Selamat dan sukses atas raihan Tsabitah Aulia meraih Juara 3 Tingkat Provinsi Hifdzil Qur\'an oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.</p>', 'Selamat dan sukses atas raihan Tsabitah Aulia meraih Juara 3 Tingkat Provinsi Hifdzil Qur\'an oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.', 'publish', 'prestasi', '/uploads/2025/04/img-20250428-wa0115-scaled.webp', '0', 4, '2025-04-30 11:19:15', 'Prestasi: Tsabitah Aulia meraih Juara 3 Tingkat Provinsi Hifdzil Qur\'an - Pondok Pesantren Raudhatul Ulum Sakatiga', 'Selamat dan sukses atas raihan Tsabitah Aulia meraih Juara 3 Tingkat Provinsi Hifdzil Qur\'an oleh siswa-siswi Pondok Pesantren Raudhatul Ulum Sakatiga.', NULL, '2026-09-12 07:03:22', '2026-09-14 15:01:37'),
(427, 'Pekan Perkenalan Santri Baru (P2SB) dan Matrikulasi T.A. 2026/2027 PPRU Sakatiga Resmi Dibuka', 'pekan-perkenalan-santri-baru-p2sb-dan-matrikulasi-ta-20262027-ppru-sakatiga-resmi-dibuka', '<p><strong>Sakatiga, Ogan Ilir</strong> — Ribuan santri baru dari berbagai penjuru nusantara resmi mengikuti upacara pembukaan Pekan Perkenalan Santri Baru (P2SB) dan Program Matrikulasi Tahun Ajaran 2026/2027 di lapangan utama pondok A Pondok Pesantren Raudhatul Ulum (PPRU) Sakatiga.</p><p>Upacara dipimpin langsung oleh Mudir PPRU, <strong>KH. Tol\'at Wafa Ahmad, Lc.</strong> Dalam amanatnya, beliau menyampaikan bahwa pondok pesantren bukan sekadar tempat menuntut ilmu umum, melainkan kawah candradimuka kaderisasi kepribadian Islam, akhlakul karimah, kemandirian, dan penempaan 10 Jati Diri Santri Raudhatul Ulum.</p><p>\"Selamat datang para mujahid dan mujahidah cilik di bumi Raudhatul Ulum Sakatiga. Niatkan langkah ananda lillahi ta\'ala, ikhlaskan hati untuk dibina dan ditempa selama 24 jam dalam lingkungan asrama yang sarat barakah ini,\" tutur Mudir dalam pidato sambutannya.</p><p>Kegiatan P2SB ini diisi dengan pengenalan tata tertib kepesantrenan, penguatan bahasa Arab dan Inggris, pengenalan sistem muadalah Al-Azhar, outbound kemandirian, serta pengenalan fasilitas laboratorium sains dan perpustakaan digital.</p>', 'Upacara pembukaan P2SB tahun ajaran 2026/2027 berlangsung khidmat di lapangan utama pondok A Pondok Pesantren Raudhatul Ulum Sakatiga, dihadiri seluruh santri baru, pengasuh, dan asatidz.', 'publish', 'post', '/uploads/2026/09/ppru-gedung-utama-1789405088-850X2.webp', 344, NULL, '2026-09-05 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 16:58:08'),
(428, 'Haflah Milad ke-76 dan Wisuda Santri Kelas Akhir Raudhatul Ulum Berlangsung Penuh Haru', 'haflah-milad-ke-76-dan-wisuda-santri-kelas-akhir-raudhatul-ulum-berlangsung-penuh-haru', '<p><strong>Sakatiga, Ogan Ilir</strong> — Suasana haru dan penuh rasa syukur menyelimuti wisuda akbar santri kelas akhir Pondok Pesantren Raudhatul Ulum Sakatiga yang dirangkaikan dengan peringatan Haflah Milad ke-76 berdirinya pesantren.</p><p>Ratusan wisudawan dan wisudawati dari jenjang Madrasah Aliyah Raudhatul Ulum (MARU), SMAIT Raudhatul Ulum, Madrasah Tsanawiyah (MATSARU), dan SMPIT Raudhatul Ulum secara resmi dilepas untuk melanjutkan estafet perjuangan ke jenjang pendidikan tinggi.</p><p>Mudir Pesantren bersama jajaran pimpinan Yayasan Perguruan Islam Raudhatul Ulum Sakatiga (YAPIRUS) mengalungkan selempang tanda kelulusan kepada wisudawan terbaik bidang akademik, tahfidz Qur\'an 30 juz mutqin, dan teladan kedisiplinan organisasi.</p>', 'PPRU Sakatiga menggelar resepsi kesyukuran Haflah Milad ke-76 sekaligus wisuda akbar ratusan santri kelas akhir MARU, SMAIT, MATSARU, dan SMPIT di Gedung Serbaguna pondok A.', 'publish', 'post', '/uploads/2026/09/ppru-gedung-utama-1789405116-VVrKy.webp', 691, NULL, '2026-08-27 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 16:58:36'),
(429, 'Pelepasan Delegasi Alumni MARU Raudhatul Ulum Sakatiga Lolos Seleksi Beasiswa Al-Azhar Kairo Mesir', 'pelepasan-delegasi-alumni-maru-raudhatul-ulum-sakatiga-lolos-seleksi-beasiswa-al-azhar-kairo-mesir', '<p><strong>Sakatiga</strong> — Hubungan historis dan akademis antara Pondok Pesantren Raudhatul Ulum Sakatiga dengan Al-Azhar Al-Syarif Kairo Mesir kembali terbukti nyata. Sebanyak 18 alumni Madrasah Aliyah Raudhatul Ulum (MARU) secara resmi dilepas untuk melanjutkan studi ke Universitas Al-Azhar Kairo Mesir tahun akademik ini.</p><p>Keberhasilan ini didukung oleh piagam muadalah (penyetaraan ijazah) resmi yang dimiliki MARU Sakatiga dari Al-Azhar sejak dekade 1990-an, di mana kurikulum dirasah islamiyah dan bahasa Arab fusha di PPRU diakui setara dengan kurikulum Ma\'ahid Azhariyyah Mesir.</p>', 'Sebagai wujud muadalah resmi, delegasi alumni MARU Sakatiga kembali diberangkatkan menempuh studi sarjana di Universitas Al-Azhar Kairo Mesir dan Universitas Islam Madinah.', 'publish', 'post', '/uploads/2026/09/ppru-gedung-utama-1789405159-r9hr6.webp', 367, NULL, '2026-08-22 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 16:59:19'),
(430, 'Sarasehan Akbar Wali Santri Baru Bersama Mudir KH. Tol\'at Wafa Ahmad, Lc.', 'sarasehan-akbar-wali-santri-baru-bersama-mudir-kh-tolat-wafa-ahmad-lc', '<p><strong>Sakatiga</strong> — Bertempat di Aula Utama pondok A, jajaran pimpinan Pondok Pesantren Raudhatul Ulum menggelar sarasehan akbar bersama seluruh wali santri baru yang mengantarkan putra-putrinya ke asrama.</p><p>Mudir KH. Tol\'at Wafa Ahmad, Lc. menekankan pentingnya keikhlasan orang tua saat menyerahkan anak ke pondok pesantren. \"Pendidikan di pesantren adalah kemitraan lahir dan batin antara orang tua di rumah dengan para asatidz di pondok. Doa orang tua di sepertiga malam adalah bahan bakar kesuksesan santri di bilik asrama,\" tegas beliau.</p>', 'Dialog terbuka dan sarasehan wali santri baru bersama Pimpinan Pondok Pesantren Raudhatul Ulum Sakatiga membahas sinergi pendidikan keluarga dan pesantren.', 'publish', 'post', '/uploads/2026/09/ppru-gedung-utama-1789405076-alnYJ.webp', 824, NULL, '2026-09-07 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 16:57:57'),
(431, 'Ujian Terbuka Tahfidz & Khotmil Qur\'an 30 Juz Bersanad Santri MATQULARU Sakatiga', 'ujian-terbuka-tahfidz-khotmil-quran-30-juz-bersanad-santri-matqularu-sakatiga', '<p><strong>Sakatiga</strong> — Suasana syahdu terdengar merdu saat para santri MATQULARU Sakatiga membacakan ayat-ayat suci Al-Qur\'an secara hafalan di hadapan dewan penguji dan para masyayikh bersanad.</p><p>Program khusus tahfidz MATQULARU mendidik santri sejak usia dini dengan metode talaqqi dan mudarasah intensif, sehingga mampu menuntaskan hafalan 30 juz mutqin lengkap dengan kaidah tajwid dan makharijul huruf yang fasih.</p>', 'Para santri cilik Madrasah Tahfizhul Qur\'an Lil Aulad (MATQULARU) sukses menjalani tasmi\' sekali duduk dan wisuda tahfidz 30 juz mutqin bersanad.', 'publish', 'post', '/uploads/ppru-tahfidz.webp', 592, NULL, '2026-09-05 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 15:04:19'),
(432, 'Perkemahan Akbar Pramuka & Pelantikan Bantara Santri Raudhatul Ulum di Bumi Perkemahan pondok B', 'perkemahan-akbar-pramuka-pelantikan-bantara-santri-raudhatul-ulum-di-bumi-perkemahan-pondok-b', '<p><strong>Indralaya</strong> — Ratusan tenda berdiri rapi di Bumi Perkemahan pondok B PPRU Sakatiga dalam rangka Perkemahan Akbar Kepanduan dan Pelantikan Penegak Bantara santri Raudhatul Ulum.</p><p>Kegiatan diisi dengan pionering, jelajah alam, pentas seni islami api unggun, dan simulasi penanggulangan bencana yang melatih kedisiplinan dan kesiapsiagaan santri di alam terbuka.</p>', 'Gugus Depan Gerakan Pramuka PPRU Sakatiga menggelar perkemahan akbar 3 hari 2 malam untuk mengasah kemandirian, ketangkasan, dan kebersamaan santri.', 'publish', 'post', '/uploads/2026/09/ppru-gedung-utama-1789405104-DEHHE.webp', 693, NULL, '2026-08-28 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 16:58:24'),
(433, 'Muhadharah Akbar 3 Bahasa (Arab, Inggris, Indonesia): Asah Percakapan & Retorika Da\'i Muda Santri', 'muhadharah-akbar-3-bahasa-arab-inggris-indonesia-asah-percakapan-retorika-dai-muda-santri', '<p><strong>Sakatiga</strong> — Kemampuan retorika dan penguasaan bahasa asing merupakan ciri khas santri Raudhatul Ulum Sakatiga. Melalui kegiatan muhadharah (latihan berpidato) berkala, santri dilatih tampil percaya diri menyampaikan gagasan dakwah secara sistematis dan lugas.</p>', 'Agenda mingguan muhadharah santri melatih kepercayaan diri santri berpidato dalam bahasa Arab fusha, Inggris, dan Indonesia di hadapan ribuan audiens.', 'publish', 'post', '/uploads/ppru-muhadharah.webp', 127, NULL, '2026-08-15 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 15:04:19'),
(434, 'Santri PPRU Sakatiga Raih Juara Umum Musabaqah Tilawatil & Hifzhil Qur\'an (MTQ/MHQ) Tingkat Provinsi', 'santri-ppru-sakatiga-raih-juara-umum-musabaqah-tilawatil-hifzhil-quran-mtqmhq-tingkat-provinsi', '<p><strong>Palembang</strong> — Prestasi membanggakan kembali ditorehkan oleh santri-santriwati Pondok Pesantren Raudhatul Ulum Sakatiga. Pada perhelatan MTQ/MHQ Tingkat Provinsi Sumatera Selatan, delegasi PPRU sukses meraih gelar Juara Umum setelah memenangkan cabang MHQ 10 Juz, 20 Juz, dan 30 Juz Putra-Putri.</p><p>Pimpinan pesantren mengapresiasi kerja keras para pembimbing dan dedikasi santri yang terus menjaga kemurnian dan kelancaran hafalan Al-Qur\'an.</p>', 'Kafilah santri Pondok Pesantren Raudhatul Ulum Sakatiga sukses memborong piala pada ajang MTQ/MHQ tingkat Sumatera Selatan di berbagai cabang lomba.', 'publish', 'post', '/uploads/ppru-mtq.webp', 700, NULL, '2026-09-12 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 15:04:19'),
(435, 'Siswa MARU & SMAIT Raudhatul Ulum Sabet Medali Emas Kompetisi Sains Madrasah (KSM)', 'siswa-maru-smait-raudhatul-ulum-sabet-medali-emas-kompetisi-sains-madrasah-ksm', '<p><strong>Ogan Ilir</strong> — Membuktikan keunggulan di bidang sains, santri Madrasah Aliyah Raudhatul Ulum (MARU) dan SMAIT Raudhatul Ulum berhasil merebut medali emas pada Kompetisi Sains Madrasah (KSM) tingkat daerah dan berhak mewakili provinsi ke tingkat nasional.</p>', 'Integrasi sains dan nilai Islam mengantarkan santri MARU dan SMAIT RU meraih juara 1 bidang Fisika Terintegrasi dan Biologi Terintegrasi KSM.', 'publish', 'post', '/uploads/ppru-ksm.webp', 353, NULL, '2026-08-26 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 15:04:19'),
(436, 'Delegasi Debat Bahasa Arab Santri PPRU Raih Gelar Best Speaker pada Festival Bahasa Nasional', 'delegasi-debat-bahasa-arab-santri-ppru-raih-gelar-best-speaker-pada-festival-bahasa-nasional', '<p><strong>Yogyakarta</strong> — Tim debat bahasa Arab Pondok Pesantren Raudhatul Ulum Sakatiga kembali menorehkan prestasi gemilang di tingkat nasional. Menghadapi puluhan pesantren dan universitas ternama, delegasi santri RU sukses meraih trofi Juara 1 dan predikat Best Speaker.</p>', 'Kecakapan tata bahasa dan retorika Arab fusha santri Raudhatul Ulum Sakatiga dinobatkan sebagai Best Speaker di ajang festival bahasa bergengsi.', 'publish', 'post', '/uploads/ppru-debat.webp', 222, NULL, '2026-09-05 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 15:04:19'),
(437, 'Santriwati Raudhatul Ulum Terpilih Mewakili Sumsel pada Ajang Perkemahan Pramuka Santri Nusantara', 'santriwati-raudhatul-ulum-terpilih-mewakili-sumsel-pada-ajang-perkemahan-pramuka-santri-nusantara', '<p><strong>Indralaya</strong> — Prestasi membanggakan kembali lahir dari pangkalan Gerakan Pramuka Gudep PPRU Sakatiga. Setelah melalui seleksi ketat kecakapan kepanduan, santriwati Raudhatul Ulum terpilih menjadi bagian dari kontingen utama Provinsi Sumatera Selatan pada Perkemahan Pramuka Santri Nusantara (PPSN).</p>', 'Ketangkasan dan disiplin kepanduan pramuka santriwati Raudhatul Ulum Sakatiga membawanya lolos seleksi mewakili kontingen Sumatera Selatan.', 'publish', 'post', '/uploads/2026/09/ppru-panahan-santri-1789405148-GsTDh.webp', 528, NULL, '2026-08-15 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 16:59:08'),
(438, 'Taujih Mudir KH. Tol\'at Wafa Ahmad, Lc: Keikhlasan dan Kesungguhan Menuntut Ilmu di Pesantren', 'taujih-mudir-kh-tolat-wafa-ahmad-lc-keikhlasan-dan-kesungguhan-menuntut-ilmu-di-pesantren', '<p><strong>Sakatiga</strong> — Dalam pertemuan rutin bersama seluruh asatidz dan santri di Masjid Utama pondok A, Mudir Pondok Pesantren Raudhatul Ulum, <strong>KH. Tol\'at Wafa Ahmad, Lc.</strong> menyampaikan tausiyah mendalam tentang hakikat tholabul \'ilmi di era modern.</p><p><em>\"Ilmu tidak akan didapatkan oleh jasad yang berleha-leha. Kehidupan asrama dengan segala disiplinnya adalah sarana pembentukan mental baja. Jangan pernah mengeluh dengan lelahnya belajar, karena lelahnya kebodohan jauh lebih pedih di kemudian hari,\"</em> tutur beliau mengutip kalam ulama salaf.</p><p>Beliau juga berpesan agar para santri senantiasa menjaga adab terhadap guru, memuliakan Al-Qur\'an, dan senantiasa berbakti serta mendoakan kedua orang tua yang telah berkorban demi masa depan mereka.</p>', '\"Pondok pesantren adalah laboratorium kehidupan. Barangsiapa yang ikhlas dan bersungguh-sungguh, Allah SWT akan bukakan pintu-pintu kemudahan baginya.\"', 'publish', 'post', '/uploads/2026/09/ppru-gedung-utama-1789405096-izl6R.webp', 459, NULL, '2026-08-31 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 16:58:16'),
(439, 'Nasihat Pimpinan: Menegakkan 10 Jati Diri Santri Raudhatul Ulum dalam Kehidupan Sehari-hari', 'nasihat-pimpinan-menegakkan-10-jati-diri-santri-raudhatul-ulum-dalam-kehidupan-sehari-hari', '<p><strong>Sakatiga</strong> — Pondok Pesantren Raudhatul Ulum memiliki 10 Jati Diri Santri yang menjadi ruh pendidikan:</p><ol><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Salimul Aqidah:</strong> Beraqidah lurus dan bersih dari syirik.</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Shahihul Ibadah:</strong> Beribadah benar sesuai tuntunan Rasulullah SAW.</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Matinul Khuluq:</strong> Berakhlak mulia, beradab, dan santun.</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Qadirun \'alal Kasbi:</strong> Mandiri dan beretos kerja tinggi.</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Mutsaqqoful Fikri:</strong> Berpengetahuan luas dalam ilmu syar\'i dan sains.</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Qowiyyul Jismi:</strong> Berbadan sehat, kuat, dan bugar.</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Mujahidun li Nafsihi:</strong> Mampu mengendalikan hawa nafsu.</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Munazzhomun fi Syu\'unihi:</strong> Berdisiplin dan tertata rapi.</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Haritsun \'ala Waqtihi:</strong> Menghargai dan memanfaatkan waktu.</li><li><span class=\"ql-ui\" contenteditable=\"false\"></span><strong>Nafi\'un li Ghairihi:</strong> Memberi manfaat seluas-luasnya bagi umat.</li></ol>', 'Penanaman 10 Standar Diri Islami (SDI) sebagai kompas moral dan spiritual bagi seluruh santri dan alumni Raudhatul Ulum di manapun berada.', 'publish', 'post', '/uploads/2026/09/ppru-gedung-utama-1789405127-EVBz4.webp', 563, NULL, '2026-08-22 15:04:19', NULL, '', NULL, '2026-09-14 14:15:31', '2026-09-14 16:58:47'),
(492, 'Kemegahan Masjid Jami\' Pesantren Raudhatul Ulum Sakatiga Waktu Senja', 'masjid-jami-raudhatul-ulum-sakatiga-dusk', '<p>Pusat ibadah dan kajian keislaman santri putra dan putri Pondok Pesantren Raudhatul Ulum Sakatiga yang megah dengan menara menjulang tinggi.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-masjid-agung.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(493, 'Haflah Takhtiman & Wisuda Akbar Santri Akhir Pondok Pesantren Raudhatul Ulum', 'haflah-takhtiman-wisuda-akbar-santri-ppru-gallery', '<p>Momen sakral pelepasan ribuan santri berprestasi yang siap mengabdi dan melanjutkan studi ke universitas ternama di dalam dan luar negeri.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-wisuda-akbar.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(494, 'Atraksi Seni Bela Diri Santri Tapak Suci & Pencak Silat PPRU Sakatiga', 'atraksi-seni-bela-diri-tapak-suci-santri-ppru', '<p>Kekompakan dan ketangkasan santri dalam memperagakan jurus-jurus bela diri pencak silat pada apel tahunan pembukaan khutbatul arsy.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-pencak-silat.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(495, 'Praktikum Robotika, IoT, dan Coding Santri di Laboratorium Komputer Modern', 'praktikum-robotika-dan-coding-santri-ppru', '<p>Integrasi kurikulum sains dan teknologi modern mencetak santri yang berwawasan digital, inovatif, dan siap bersaing di era industri 4.0.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-robotika-sains.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(496, 'Latihan Memanah Sunnah Santri Raudhatul Ulum Sakatiga', 'latihan-memanah-sunnah-santri-ppru', '<p>Olahraga panahan sunnah nabawiyah melatih ketajaman konsentrasi, ketenangan jiwa, dan kekuatan fisik para santri di lapangan hijau pondok.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-panahan-santri.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(497, 'Halaqah Tahfidzul Qur\'an 30 Juz Bersama Asatidz Huffadz Mutqin', 'halaqah-tahfidzul-quran-30-juz-ppru', '<p>Suasana syahdu dan khidmat para santri menghafal dan menyetorkan hafalan Al-Qur\'an ba\'da Subuh dan ba\'da Maghrib di serambi masjid.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-halaqah-quran.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(498, 'Perpustakaan Islam Modern & Khazanah Kitab Turats Kuning', 'perpustakaan-islam-modern-dan-kitab-kuning-ppru', '<p>Fasilitas literasi komprehensif yang menyediakan ribuan jilid kitab rujukan para ulama salaf dan literatur ilmiah modern dunia.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-perpustakaan-islam.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(499, 'Panorama pondok Hijau & Gedung Pendidikan Terpadu Raudhatul Ulum', 'panorama-pondok-hijau-ppru-sakatiga', '<p>Tata ruang asri dan megah seluas puluhan hektar yang nyaman dan kondusif untuk menuntut ilmu agama dan pengetahuan umum.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-gedung-utama.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(500, 'Kunjungan Delegasi Muadalah Universitas Al-Azhar Kairo Mesir di PPRU', 'kunjungan-delegasi-universitas-al-azhar-kairo-ppru', '<p>Penandatanganan penguatan kerjasama muadalah kurikulum antara Mudir PPRU dan para syuyukh terkemuka dari Al-Azhar Mesir.</p>', NULL, 'publish', 'gallery', '/uploads/galeri/ppru-gedung-utama-1789405022-Aq65h.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:57:02'),
(501, 'Latihan Khitobah & Muhadharah 3 Bahasa: Arab, Inggris, dan Indonesia', 'latihan-khitobah-muhadharah-3-bahasa-ppru', '<p>Penggemblengan public speaking dan retorika dakwah mingguan santri di asrama untuk melatih kepemimpinan ummat masa depan.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-muhadharah.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(502, 'Kafilah Musabaqah Tilawatil Qur\'an (MTQ) Santri Raudhatul Ulum', 'kafilah-musabaqah-tilawatil-quran-santri-ppru', '<p>Prestasi gemilang kafilah santri PPRU dalam ajang MTQ cabang qira\'at sab\'ah, fahmil qur\'an, dan syarhil qur\'an tingkat provinsi dan nasional.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-mtq.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(503, 'Perkemahan LP3 Pramuka Santri Pondok Pesantren Raudhatul Ulum Sakatiga', 'perkemahan-lp3-pramuka-santri-ppru', '<p>Semangat kemandirian, kepemimpinan, dan persaudaraan santri penggalang dan penegak dalam kegiatan kepramukaan alam bebas.</p>', NULL, 'publish', 'gallery', '/uploads/galeri/ppru-gedung-utama-1789405033-XnHYr.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:57:13'),
(504, 'Kompetisi Sains Madrasah (KSM) & Olimpiade Riset Ilmiah Santri', 'kompetisi-sains-madrasah-dan-olimpiade-riset-santri-ppru', '<p>Santri Raudhatul Ulum membuktikan keunggulan di bidang sains terintegrasi keislaman: Matematika, Fisika, Kimia, dan Biologi.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-ksm.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(505, 'Tim Debat Bahasa Arab & Pemikiran Islam Santri PPRU', 'tim-debat-bahasa-arab-dan-pemikiran-islam-ppru', '<p>Asah argumentasi nalar kritis santri dalam forum debat ilmiah berbahasa Arab fasih bertaraf nasional.</p>', NULL, 'publish', 'gallery', '/uploads/ppru-debat.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:40:24'),
(506, 'Sarasehan Nasional Alumni & Tokoh Inspiratif di pondok PPRU', 'sarasehan-nasional-alumni-dan-tokoh-ppru', '<p>Temu akbar ribuan alumni lintas angkatan yang berkiprah di bidang birokrasi, akademisi, wirausaha syariah, dan dakwah Islam internasional.</p>', NULL, 'publish', 'gallery', '/uploads/galeri/ppru-gedung-utama-1789405042-Sozbh.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:57:22'),
(507, 'Pekan Pengenalan Nilai Panca Jiwa & Adab Kepesantrenan Santri Baru', 'pekan-pengenalan-panca-jiwa-santri-baru-ppru', '<p>Menanamkan keikhlasan, kesederhanaan, berdikari, ukhuwah islamiyyah, dan kebebasan berpikir yang bertanggung jawab dalam jiwa setiap santri.</p>', NULL, 'publish', 'gallery', '/uploads/galeri/ppru-gedung-utama-1789405051-ZUcIZ.webp', '0', NULL, NULL, NULL, NULL, NULL, '2026-09-14 16:40:24', '2026-09-14 16:57:31'),
(508, 'Gerakan Pramuka Gudep PPRU', 'pramuka-ppru', '<p>Gerakan Pramuka Gugus Depan Pondok Pesantren Raudhatul Ulum Sakatiga merupakan wadah pembinaan kepanduan santri yang berlandaskan Tri Satya, Dasa Darma, dan nilai-nilai Islam. Melatih kemandirian, kedisiplinan, survival skills, pertolongan pertama, serta kepemimpinan lapangan melalui perkemahan rutin tahunan (LP3RU).</p>', 'Kepanduan santri berlandaskan Dasa Darma & Sunnah Rasulullah SAW.', 'publish', 'ekskul', '/uploads/ppru-pramuka.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(509, 'Tapak Suci & Pencak Silat Santri', 'tapak-suci-pencak-silat', '<p>Ekstrakurikuler bela diri Pencak Silat Tapak Suci Putera Muhammadiyah melatih santri dalam olah fisik, teknik tangkisan, kuncian, dan jurus seni bela diri. Menanamkan mental ksatria dengan semboyan \"Dengan Iman dan Akhlak Saya Menjadi Kuat, Tanpa Iman dan Akhlak Saya Menjadi Lemah\". Rutin menjuarai kejuaraan silat tingkat daerah dan nasional.</p>', 'Seni bela diri santri untuk kebugaran fisik, mental ksatria, dan prestasi atlet.', 'publish', 'ekskul', '/uploads/ppru-pencak-silat.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(510, 'Klub Panahan Santri (PPRU Archery)', 'klub-panahan-ppru-archery', '<p>Olahraga sunnah memanah (Archery) dibina langsung oleh instruktur bersertifikat Perpani. Mengajarkan fokus, ketenangan jiwa, kekuatan tarikan busur, dan akurasi bidikan. Santri dilatih menggunakan busur standar nasional (standard bow) maupun horsebow tradisional.</p>', 'Olahraga sunnah memanah untuk melatih fokus, ketenangan batin, dan akurasi tinggi.', 'publish', 'ekskul', '/uploads/official/panahan-santri.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-15 17:45:39'),
(511, 'Seni Tilawah & Hadroh Rebana', 'seni-tilawah-dan-hadroh', '<p>Wadah pengembangan bakat seni Islam yang mencakup Seni Baca Al-Qur\'an (Nagham/Mujawwad) dan Korps Hadroh Shalawat Al-Banjari. Santri dibimbing melafalkan maqam tilawah (Bayati, Shoba, Hijaz, Nahawand, Rast, Sika, Jiharkah) serta mengiringi lantunan shalawat nabi dengan tabuhan rebana ritmis harmonis.</p>', 'Pembinaan seni baca Qur\'an maqamat dan lantunan shalawat hadroh rebana.', 'publish', 'ekskul', '/uploads/ppru-tahfidz.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(512, 'Khat & Kaligrafi Islam (Khattat)', 'khat-dan-kaligrafi-islam', '<p>Klub Kaligrafi Islam membina santri menguasai kaidah khat Arab klasik seperti Naskhi, Riq\'ah, Tsuluts, Diwani, Farisi, dan Kufi. Karya santri rutin dipamerkan pada Haflah Ikhtitam dan menorehkan prestasi dalam ajang Musabaqah Khaththil Qur\'an (MKQ).</p>', 'Mahakarya seni tulisan Arab indah bersanad kaidah khat nusantara dan Timur Tengah.', 'publish', 'ekskul', '/uploads/official/kbm-santri-0098.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-15 17:46:11'),
(513, 'Arabic & English Debate Club', 'arabic-english-debate-club', '<p>Jam\'iyyah Lughawiyyah (Language Club) khusus mengasah kecakapan santri dalam debat publik, orasi (khitobah/speech), storytelling, dan penulisan esai dalam dua bahasa internasional (Bahasa Arab & Bahasa Inggris). Menjadi ujung tombak diplomasi dan prestasi santri di ajang olimpiade bahasa.</p>', 'Klub debat dan pidato bahasa Arab & Inggris untuk diplomasi santri global.', 'publish', 'ekskul', '/uploads/official/kegiatan-santri-waw1981.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-15 17:46:11'),
(514, 'Sains, Robotika & Koding Santri', 'sains-robotika-koding', '<p>Menghadirkan sinergi antara sains, teknologi, dan akhlak santri. Santri belajar pemrograman mikrokontroler (Arduino, IoT), perakitan robot line follower, pemrograman web/aplikasi dasar, serta eksperimen sains terapan di laboratorium madrasah modern PPRU.</p>', 'Pengembangan teknologi modern, robotika madrasah, dan dasar-dasar pemrograman santri.', 'publish', 'ekskul', '/uploads/ppru-robotika-sains.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(515, 'Jurnalistik Santri & TV Raudhatul Ulum', 'jurnalistik-santri-tvru', '<p>Komunitas santri jurnalis dan multimedia yang mengelola buletin santri, fotografi acara pesantren, penulisan berita web resmi, podcast santri, serta produksi video siaran TV Raudhatul Ulum (TVRU). Melatih santri melek media dan dakwah digital.</p>', 'Laboratorium media kreatif: fotografi, videografi, podcast, dan dakwah digital santri.', 'publish', 'ekskul', '/uploads/ppru-haflah.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(516, 'Ustadz H. Ahmad Al-Ghifari, Lc., M.Ag.', 'ahmad-al-ghifari', '<p>Alumni Madrasah Aliyah Raudhatul Ulum (MARU) Sakatiga tahun 2018. Melanjutkan studi S1 di Fakultas Ushuluddin Universitas Al-Azhar Kairo Mesir dan menyelesaikan S2 Kajian Islam. Saat ini aktif sebagai akademisi, da\'i, dan pengajar bahasa Arab.</p>', 'Alumni MA Raudhatul Ulum 2018 • S1 Universitas Al-Azhar Kairo Mesir', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(517, 'Dr. Muhammad Fadhil Rahmani, S.T., M.Sc.', 'muhammad-fadhil-rahmani', '<p>Lulusan SMA IT Raudhatul Ulum Sakatiga tahun 2015. Menyelesaikan S1 Teknik Elektro Institut Teknologi Bandung (ITB) dan S2/S3 Energi Terbarukan di KAUST Arab Saudi. Kini berkarir sebagai peneliti energi terbarukan.</p>', 'Alumni SMA IT Raudhatul Ulum 2015 • Dosen & Peneliti Teknologi Energi ITB', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(518, 'H. Syauqi Abdullah, Lc., M.H.', 'syauqi-abdullah', '<p>Menyelesaikan pendidikan muadalah di PPRU Sakatiga tahun 2017 dan diterima di Universitas Islam Madinah (UIM) jurusan Syariah Islamiyah. Aktif sebagai konsultan hukum syariah dan pimpinan pondok mitra.</p>', 'Alumni MA Raudhatul Ulum 2017 • S1 Universitas Islam Madinah Arab Saudi', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(519, 'dr. Fatimah Az-Zahra, Sp.A.', 'fatimah-az-zahra', '<p>Alumni angkatan 2014 SMA IT Raudhatul Ulum Sakatiga. Meraih gelar Dokter dari FK Universitas Sriwijaya (UNSRI) dan spesialis anak. Aktif mengabdi dalam layanan kesehatan masyarakat dan poskestren.</p>', 'Alumni SMA IT Raudhatul Ulum 2014 • Dokter Spesialis Anak RSUP Dr. Mohammad Hoesin', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(520, 'Ustadzah Nurul Hidayah, S.Pd.I., M.Pd.', 'nurul-hidayah', '<p>Alumni program Madrasah Aliyah Tahfizhul Qur\'an Raudhatul Ulum (MATQULARU) 30 Juz tahun 2016. Mengajar sebagai dosen di UIN Raden Fatah Palembang dan pengasuh halaqah tahfidz putri.</p>', 'Alumni MATQULARU 2016 • Dosen Pendidikan Agama Islam UIN Raden Fatah', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(521, 'Muhammad Rizki Pratama, S.Kom., M.T.', 'muhammad-rizki-pratama', '<p>Lulusan SMA IT Raudhatul Ulum Sakatiga tahun 2019. Menyelesaikan S1 Ilmu Komputer Universitas Indonesia (UI) dan S2 Sistem Informasi. Bekerja sebagai lead engineer di perusahaan teknologi finansial terkemuka.</p>', 'Alumni SMA IT Raudhatul Ulum 2019 • Senior Software Engineer Jakarta', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(522, 'Ustadz Bilal Ramadhan, Lc.', 'bilal-ramadhan', '<p>Alumni penerima beasiswa penuh Kemenag untuk studi di Universitas Al-Azhar Kairo Mesir angkatan kelulusan MARU 2020. Penulis buku fiqih muamalah kontemporer dan aktivis PCI Nahdlatul Ulama / Muhammadiyah Mesir.</p>', 'Alumni MA Raudhatul Ulum 2020 • Mahasiswa Pascasarjana Al-Azhar Kairo Mesir', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(523, 'Aisyah Zahira, S.E., M.E.', 'aisyah-zahira', '<p>Lulusan tahun 2018 yang menempuh pendidikan Sarjana Ekonomi Syariah di Institut Pertanian Bogor (IPB). Saat ini mendedikasikan ilmunya sebagai analis pembiayaan mikro syariah.</p>', 'Alumni SMA IT Raudhatul Ulum 2018 • Analis Keuangan Syariah Bank Syariah Indonesia', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(524, 'Kapten Inf. Salman Al-Farisi, S.Tr.Han.', 'salman-al-farisi', '<p>Lulusan SMA IT Raudhatul Ulum tahun 2016 yang berhasil menembus Akademi Militer (Akmil) Magelang. Memadukan disiplin santri berakhlak Qur\'ani dengan kepemimpinan militer nasional.</p>', 'Alumni SMA IT Raudhatul Ulum 2016 • Perwira TNI Angkatan Darat', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(525, 'Ustadz Zaidan Al-Anshari, S.H.I., M.H.', 'zaidan-al-anshari', '<p>Lulusan Madrasah Aliyah tahun 2021 yang menyelesaikan S1 Hukum Islam UIN Sunan Kalijaga dengan predikat Cum Laude. Mengabdi di lembaga peradilan keagamaan.</p>', 'Alumni MA Raudhatul Ulum 2021 • Hakim Peradilan Agama Mahkamah Agung RI', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(526, 'Khadijah Maryam, S.Farm., Apt.', 'khadijah-maryam', '<p>Lulusan SMA IT Raudhatul Ulum tahun 2019. Menyelesaikan profesi apoteker di Fakultas Farmasi Universitas Gadjah Mada (UGM) dan kini meneliti formulasi obat herbal alami.</p>', 'Alumni SMA IT Raudhatul Ulum 2019 • Apoteker & Formulator Herbal UGM', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(527, 'Ustadz H. Farhan Maulana, S.Ag., M.Ag.', 'farhan-maulana', '<p>Lulusan MARU tahun 2017 dan Institut Agama Islam Raudhatul Ulum (IAI NRU). Berdedikasi kembali ke almamater untuk membina generasi santri baru dan mengembangkan dakwah pesantren.</p>', 'Alumni MARU 2017 • Pengajar & Sekretariat YAPIRUS Sakatiga', 'publish', 'alumni', '/uploads/default-avatar.webp', '0', 1, '2026-09-14 21:06:13', NULL, NULL, NULL, '2026-09-14 21:06:13', '2026-09-14 21:06:13'),
(528, 'Panorama Kampus Terpadu Pondok Pesantren Raudhatul Ulum dari Udara', 'panorama-kampus-terpadu-ppru-drone', 'Dokumentasi udara kawasan terpadu Pondok Pesantren Raudhatul Ulum Sakatiga seluas lebih dari 60 hektar, mencakup masjid jami\', asrama putra/putri, gedung madrasah, dan sarana olahraga.', NULL, 'publish', 'gallery', '/uploads/official/drone-raudhatul-ulum.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(529, 'Pemandangan Asri Danau Telok Putih Sakatiga Kawasan Pesantren', 'pemandangan-asri-danau-telok-putih-drone', 'Danau Telok Putih yang membentang asri di lingkungan Pesantren Raudhatul Ulum, menciptakan ekosistem hijau yang sejuk dan kondusif bagi proses thalabul ilmi santri.', NULL, 'publish', 'gallery', '/uploads/official/drone-danau-telok-putih.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(530, 'Suasana Khidmat Halaqah Ngaji Sore & Pengajian Kitab Santri', 'suasana-khidmat-ngaji-sore-santri', 'Aktivitas santri saat menyimak pembacaan kitab turats (kitab kuning) dan setoran hafalan Al-Qur\'an pada halaqah ba\'da Ashar di masjid utama.', NULL, 'publish', 'gallery', '/uploads/official/ngaji-sore.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(531, 'Latihan Olahraga Sunnah Panahan (Archery) Santri Raudhatul Ulum', 'latihan-olahraga-panahan-santri-ppru', 'Pembinaan karakter dan konsentrasi santri melalui ekstrakurikuler panahan sebagai wujud penghidupan olahraga sunnah Rasulullah SAW.', NULL, 'publish', 'gallery', '/uploads/official/panahan-santri.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(532, 'Keluarga Besar Asatidz & Santri dalam Kegiatan Haflah Takhtiman', 'kegiatan-santri-dan-asatidz-waw1981', 'Dokumentasi momen berharga kebersamaan para asatidz dan santri dalam rangkaian agenda besar kesyukuran dan haflah pesantren.', NULL, 'publish', 'gallery', '/uploads/official/kegiatan-santri-waw1981.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(533, 'Pemberian Piagam & Apresiasi Prestasi Akademik Santri Berprestasi', 'apresiasi-prestasi-santri-waw1985', 'Penyerahan penghargaan atas capaian prestasi akademik dan tahfidzul qur\'an santri sebagai motivasi keteladanan bagi seluruh santri PPRU.', NULL, 'publish', 'gallery', '/uploads/official/kegiatan-santri-waw1985.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(534, 'Dinamika Pembelajaran & Kegiatan Belajar Mengajar (KBM) Santri', 'kegiatan-belajar-mengajar-santri-0054', 'Suasana aktif kelas interaktif santri dalam menyerap materi ilmu pengetahuan agama dan umum dengan bimbingan asatidz.', NULL, 'publish', 'gallery', '/uploads/official/kbm-santri-0054.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(535, 'Praktek dan Diskusi Kolaboratif Santri di Ruang Kelas', 'diskusi-kolaboratif-santri-0098', 'Para santri berdiskusi mengkaji materi pelajaran secara kelompok guna mengasah nalar kritis dan kemampuan komunikasi dwi-bahasa.', NULL, 'publish', 'gallery', '/uploads/official/kbm-santri-0098.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(536, 'Konsentrasi dan Kedisiplinan Santri dalam Pembelajaran Harian', 'kedisiplinan-santri-pembelajaran-0152', 'Kedisiplinan yang menjadi ciri khas kultur santri Raudhatul Ulum dalam setiap sesi pembelajaran formal maupun kepesantrenan.', NULL, 'publish', 'gallery', '/uploads/official/kbm-santri-0152.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(537, 'Apel Akbar & Barisan Santri Pondok Pesantren Raudhatul Ulum', 'apel-akbar-santri-raudhatul-ulum-4680', 'Barisan rapi santri saat apel mingguan dalam rangka memupuk jiwa kepemimpinan, kepatuhan, dan semangat ukhuwah islamiyah.', NULL, 'publish', 'gallery', '/uploads/official/upacara-santri-4680.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(538, 'Lanskap Hijau Kawasan Asrama dan Fasilitas Pesantren', 'lanskap-kawasan-asrama-santri-9936', 'Lingkungan pesantren yang dikelilingi pepohonan rindang dan tata ruang teratur untuk kenyamanan istirahat dan ibadah santri.', NULL, 'publish', 'gallery', '/uploads/official/drone-lingkungan-9936.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04'),
(539, 'Kawasan Lapangan Olahraga & Sarana Prasarana Terpadu PPRU', 'lapangan-olahraga-sarana-ppru-9941', 'Fasilitas lapangan olahraga santri yang luas mendukung pembentukan santri yang sehat, tangguh, dan bertubuh bugar.', NULL, 'publish', 'gallery', '/uploads/official/drone-lingkungan-9941.webp', '0', NULL, '2026-09-15 17:39:04', NULL, NULL, NULL, '2026-09-15 17:39:04', '2026-09-15 17:39:04');
