(62, 'ppdb_tahfidz', 'Tahfidz minimal 3 Juz: Keringanan biaya pendaftaran & beasiswa santri berprestasi.\r\nTahfidz 10 Juz atau lebih: Beasiswa SPP berkala dan pembinaan khusus Sanad / Mutqin di MATQULARU.\r\nMengikuti tes sima\'an tahfidz bersama dewan musyrif Al-Qur\'an PPRU.', 'ppdb', '2026-09-14 15:01:38', '2026-09-14 20:49:06'),
(63, 'ppdb_form_tracks', 'Jalur Reguler / Tes Pesantren\r\nJalur Prestasi Akademik & Non-Akademik\r\nJalur Hafizh Al-Qur\'an (Tahfidz)\r\nJalur Alumni MTs/SMPIT Raudhatul Ulum\r\nJalur Beasiswa / Afirmasi Khusus', 'ppdb', '2026-09-14 15:01:38', '2026-09-14 20:49:07'),
