(79, 'ppdb_flyer_title', 'Brosur & Poster Resmi PSB Online', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(80, 'ppdb_flyer_desc', 'Dapatkan panduan lengkap penerimaan santri baru, profil keunggulan, rincian biaya, serta tata cara pendaftaran santri baru.', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(81, 'ppdb_flyer_image', '/uploads/popup/popup-ppdb.webp', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(82, 'ppdb_unit_badge', 'Multi-Unit Pendidikan Terpadu', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(83, 'ppdb_unit_title', 'PILIH UNIT PENDIDIKAN TUJUAN', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(84, 'ppdb_unit_desc', 'Pondok Pesantren Raudhatul Ulum Sakatiga menaungi 8 unit pendidikan resmi yang terstruktur mulai dari Madrasah, TK Islam, Sekolah Islam Terpadu (JSIT), hingga Perguruan Tinggi Islam.', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(85, 'ppdb_alur_title', 'ALUR PENDAFTARAN SANTRI BARU (PSB)', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(86, 'ppdb_alur_desc', '5 Tahapan mudah dan transparan pendaftaran santri baru Pondok Pesantren Raudhatul Ulum Sakatiga', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(87, 'ppdb_step_1_title', 'Pendaftaran Online', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(88, 'ppdb_step_1_desc', 'Mengisi formulir PSB melalui portal website resmi ini dengan data calon santri dan orang tua secara lengkap.', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(89, 'ppdb_step_1_sub', 'Portal aktif 24 jam', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(90, 'ppdb_step_2_title', 'Transfer & Berkas', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(91, 'ppdb_step_2_desc', 'Membayar biaya pendaftaran ke rekening BSI resmi pesantren dan mengunggah bukti transfer serta berkas KK/Akta.', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(92, 'ppdb_step_2_sub', 'Biaya Rp 250.000,- via Bank BSI', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(93, 'ppdb_step_3_title', 'Ujian Seleksi & Wawancara', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(94, 'ppdb_step_3_desc', 'Mengikuti tes potensi akademik, tes membaca Al-Qur\'an/tahfidz, dan wawancara kesiapan orang tua serta santri.', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(95, 'ppdb_step_3_sub', 'Jadwal diinfokan via WhatsApp', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(96, 'ppdb_step_4_title', 'Pengumuman Kelulusan', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(97, 'ppdb_step_4_desc', 'Mengecek hasil seleksi kelulusan melalui website dan notifikasi resmi WhatsApp panitia PSB.', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(98, 'ppdb_step_4_sub', 'Daftar ulang & fitting seragam', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(99, 'ppdb_step_5_title', 'Masuk Asrama (P2SB)', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(100, 'ppdb_step_5_desc', 'Kedatangan santri ke asrama, serah terima dengan Mudir dan pengasuh, serta mengikuti Pekan Perkenalan Santri Baru (P2SB).', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(101, 'ppdb_step_5_sub', 'Khutbatul Arsy & pembagian kamar santri', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(102, 'ppdb_alur', 'Siapkan berkas foto/scan bukti transfer biaya pendaftaran melalui Bank Syariah Indonesia (BSI) nomor rekening 7011304251 a.n. Pondok Pesantren Raudhatul Ulum.\r\nSiapkan berkas foto/scan akta kelahiran dan kartu keluarga.\r\nMengisi formulir PPDB secara online pada website resmi.\r\nKonfirmasi pengisian formulir kepada panitia melalui WhatsApp (0812-7890-1950).\r\nPendaftaran selesai dan berkas diverifikasi tim panitia untuk tahapan tes wawancara dan tahfidz.', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(103, 'ppdb_jalur_title', 'JALUR PENERIMAAN SANTRI BARU', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(104, 'ppdb_jalur_desc', 'Tersedia berbagai pilihan jalur penerimaan sesuai bakat, hafalan Al-Qur\'an, dan prestasi santri', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
(105, 'ppdb_jalur_reguler_title', 'Jalur Reguler (Mandiri)', 'ppdb', '2026-09-14 20:49:06', '2026-09-14 20:49:06'),
