(123, 'ppdb_video_desc', 'Saksikan lingkungan belajar, masjid agung, asrama santri, laboratorium, dan aktivitas harian di Pondok Pesantren Raudhatul Ulum Sakatiga', 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
