(125, 'ppdb_faq_title', 'PERTANYAAN SERING DIAJUKAN (FAQ)', 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
(126, 'ppdb_faq_desc', 'Jawaban seputar kehidupan berasrama dan pendaftaran santri baru di PPRU Sakatiga', 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
(127, 'ppdb_faq', 'Apakah santri wajib tinggal di asrama (Boarding)? | Untuk jenjang Madrasah Aliyah (MARU), Madrasah Tsanawiyah (MATSARU), SMAIT RU, SMPIT RU, dan MATQULARU, seluruh santri diwajibkan tinggal di asrama (Boarding School) dengan pengawasan 24 jam bersama musyrif/musyrifah asrama. Sedangkan untuk jenjang MI (MIRU) dan TK (TAKIRU) bersifat Full Day School (non-asrama).\r\nBagaimana aturan kunjungan orang tua dan izin pulang santri? | Kunjungan orang tua dijadwalkan pada hari Ahad sesuai kalender kepesantrenan tanpa mengganggu jadwal belajar santri. Perizinan pulang diberikan pada liburan semester resmi pesantren atau urusan mendesak dengan izin pengasuhan asrama.\r\nApakah lulusan MARU dan SMAIT dapat melanjutkan ke universitas luar negeri? | Ya, benar. Madrasah Aliyah Raudhatul Ulum (MARU) memiliki piagam muadalah (penyetaraan ijazah) resmi dari Universitas Al-Azhar Kairo Mesir, sehingga alumni dapat langsung mendaftar ke Al-Azhar Kairo dan Universitas Islam Madinah. Selain itu, ijazah nasional Kemenag dan Kemendikbud diakui penuh untuk masuk PTN (SNBP, SNBT, SPAN-PTKIN) di seluruh Indonesia.\r\nBagaimana program pembinaan tahfidz Al-Qur\'an di pesantren? | Setiap santri mendapatkan halaqah tahfidz harian ba\'da Subuh dan ba\'da Maghrib. Khusus santri unit MATQULARU, pembinaan dilakukan secara intensif dengan target mutqin 30 juz dan sanad.', 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
(128, 'ppdb_closing_title', 'SIAP MEMULAI LANGKAH MENJADI SANTRI KHOIRU UMMAH?', 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
(129, 'ppdb_closing_desc', 'Jangan lewatkan kesempatan emas bergabung dengan keluarga besar Pondok Pesantren Raudhatul Ulum Sakatiga. Kuota kelas terbatas setiap tahunnya.', 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
(130, 'ppdb_closing_btn_text', 'Isi Formulir Pendaftaran Sekarang', 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
(131, 'ppdb_form_status', 1, 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
(132, 'ppdb_form_closed_message', 'Pendaftaran PPDB online saat ini sedang ditutup sementara atau kuota telah terpenuhi. Silakan hubungi panitia melalui WhatsApp untuk informasi gelombang berikutnya.', 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
(133, 'ppdb_form_announcement', 'Pastikan nomor WhatsApp yang diisi aktif untuk pengiriman kartu peserta ujian dan informasi jadwal seleksi.', 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
