(143, 'ppdb_form_schema', '[\n    {\n        \"key\": \"wave\",\n        \"label\": \"Gelombang Pendaftaran\",\n        \"section\": \"pilihan\",\n        \"type\": \"select\",\n        \"required\": false,\n        \"enabled\": true,\n        \"options\": [\n            \"Gelombang 1 (Early Bird)\",\n            \"Gelombang 2 (Reguler)\",\n            \"Gelombang 3 (Prestasi)\"\n        ],\n        \"placeholder\": \"Pilih Gelombang...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"track\",\n        \"label\": \"Jalur Pendaftaran\",\n        \"section\": \"pilihan\",\n        \"type\": \"select\",\n        \"required\": false,\n        \"enabled\": true,\n        \"options\": [\n            \"Jalur Reguler \\/ Tes Mandiri\",\n            \"Jalur Prestasi Akademik & Non-Akademik\",\n            \"Jalur Hafizh Al-Qur\'an (Tahfidz)\",\n            \"Jalur Alumni MTs \\/ SMPIT Raudhatul Ulum\",\n            \"Jalur Beasiswa \\/ Afirmasi\"\n        ],\n        \"placeholder\": \"Pilih Jalur Masuk...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"program_type\",\n        \"label\": \"Program Pilihan\",\n        \"section\": \"pilihan\",\n        \"type\": \"select\",\n        \"required\": false,\n        \"enabled\": true,\n        \"options\": [\n            \"Boarding School (Asrama Santri)\",\n            \"Full Day School (Sekolah Terpadu)\"\n        ],\n        \"placeholder\": \"Pilih Program Belajar...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"full_name\",\n        \"label\": \"Nama Lengkap Siswa\",\n        \"section\": \"siswa\",\n        \"type\": \"text\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Masukkan nama lengkap sesuai akta...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"birth_place\",\n        \"label\": \"Tempat Lahir Siswa\",\n        \"section\": \"siswa\",\n        \"type\": \"text\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Kota kelahiran...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"birth_date\",\n        \"label\": \"Tanggal Lahir Siswa\",\n        \"section\": \"siswa\",\n        \"type\": \"date\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"gender\",\n        \"label\": \"Jenis Kelamin\",\n        \"section\": \"siswa\",\n        \"type\": \"select\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [\n            \"Laki-laki\",\n            \"Perempuan\"\n        ],\n        \"placeholder\": \"Pilih Jenis Kelamin...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"address\",\n        \"label\": \"Alamat Tempat Tinggal\",\n        \"section\": \"siswa\",\n        \"type\": \"textarea\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Jalan, RT\\/RW, Kelurahan, Kecamatan, Kota\\/Kabupaten...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"living_with\",\n        \"label\": \"Tinggal Bersama\",\n        \"section\": \"siswa\",\n        \"type\": \"select\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [\n            \"Orang Tua\",\n            \"Wali\",\n            \"Asrama \\/ Boarding\",\n            \"Kost\",\n            \"Lainnya\"\n        ],\n        \"placeholder\": \"Pilih Tempat Tinggal...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"child_order\",\n        \"label\": \"Anak ke -\",\n        \"section\": \"siswa\",\n        \"type\": \"number\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"1\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"siblings_count\",\n        \"label\": \"Dari Jumlah Saudara\",\n        \"section\": \"siswa\",\n        \"type\": \"number\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"1\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"previous_school\",\n        \"label\": \"Asal Sekolah (SMP \\/ MTs)\",\n        \"section\": \"siswa\",\n        \"type\": \"text\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Nama SMP \\/ MTs asal...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"nisn\",\n        \"label\": \"Nomor Induk Siswa Nasional (NISN)\",\n        \"section\": \"siswa\",\n        \"type\": \"text\",\n        \"required\": false,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Nomor NISN 10 digit (jika ada)...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"hobby\",\n        \"label\": \"Hobi Calon Siswa\",\n        \"section\": \"siswa\",\n        \"type\": \"text\",\n        \"required\": false,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Membaca, Futsal, Robotika, dll...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"favorite_subject\",\n        \"label\": \"Bidang Studi Paling Disukai\",\n        \"section\": \"siswa\",\n        \"type\": \"text\",\n        \"required\": false,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Matematika, IPA, PAI, Bahasa Arab, dll...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"ambition\",\n        \"label\": \"Cita-cita\",\n        \"section\": \"siswa\",\n        \"type\": \"text\",\n        \"required\": false,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Dokter, Ulama, Dosen, Pengusaha, dll...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"achievements\",\n        \"label\": \"Prestasi yang Pernah Diraih\",\n        \"section\": \"siswa\",\n        \"type\": \"textarea\",\n        \"required\": false,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Sebutkan prestasi akademik, tahfidz, olahraga atau lomba yang pernah diraih...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"phone\",\n        \"label\": \"Nomor HP \\/ WhatsApp Siswa\",\n        \"section\": \"siswa\",\n        \"type\": \"tel\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"08xxxxxxxxxx\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"father_name\",\n        \"label\": \"Nama Lengkap Ayah \\/ Wali\",\n        \"section\": \"ayah\",\n        \"type\": \"text\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Nama lengkap ayah\\/wali...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"father_birth_place\",\n        \"label\": \"Tempat Lahir Ayah\",\n        \"section\": \"ayah\",\n        \"type\": \"text\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Kota kelahiran ayah...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"father_birth_date\",\n        \"label\": \"Tanggal Lahir Ayah\",\n        \"section\": \"ayah\",\n        \"type\": \"date\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"father_address\",\n        \"label\": \"Alamat Ayah \\/ Wali\",\n        \"section\": \"ayah\",\n        \"type\": \"textarea\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Alamat domisili ayah\\/wali...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"father_education\",\n        \"label\": \"Pendidikan Terakhir Ayah\",\n        \"section\": \"ayah\",\n        \"type\": \"select\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [\n            \"Tidak Sekolah\",\n            \"SD \\/ Sederajat\",\n            \"SMP \\/ Sederajat\",\n            \"SMA \\/ SMK \\/ MA\",\n            \"Diploma (D1\\/D2\\/D3)\",\n            \"Sarjana (S1)\",\n            \"Magister (S2)\",\n            \"Doktor (S3)\"\n        ],\n        \"placeholder\": \"Pilih Pendidikan...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"father_job\",\n        \"label\": \"Pekerjaan Ayah\",\n        \"section\": \"ayah\",\n        \"type\": \"select\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [\n            \"PNS \\/ Polisi \\/ TNI\",\n            \"Wiraswasta \\/ Pengusaha\",\n            \"Karyawan Swasta \\/ BUMN\",\n            \"Guru \\/ Dosen\",\n            \"Petani \\/ Pekebun\",\n            \"Buruh \\/ Tenaga Harian\",\n            \"Pensiunan\",\n            \"Lainnya\"\n        ],\n        \"placeholder\": \"Pilih Pekerjaan...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"father_income\",\n        \"label\": \"Penghasilan Ayah per Bulan\",\n        \"section\": \"ayah\",\n        \"type\": \"select\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [\n            \"Tidak Berpenghasilan\",\n            \"< Rp 1.000.000\",\n            \"Rp 1.000.000 - Rp 3.000.000\",\n            \"Rp 3.000.000 - Rp 5.000.000\",\n            \"Rp 5.000.000 - Rp 10.000.000\",\n            \"> Rp 10.000.000\"\n        ],\n        \"placeholder\": \"Pilih Kisaran Penghasilan...\",\n        \"is_system\": true\n    },\n    {\n        \"key\": \"father_phone\",\n        \"label\": \"Nomor HP \\/ WhatsApp Ayah\",\n        \"section\": \"ayah\",\n        \"type\": \"tel\",\n        \"required\": false,\n        \"enabled\": tr