\"berkas\",\n        \"type\": \"file\",\n        \"required\": true,\n        \"enabled\": true,\n        \"options\": [],\n        \"placeholder\": \"Pilih file bukti transfer (Maks 5 MB)\",\n        \"is_system\": true\n    }\n]', 'ppdb', '2026-09-14 20:49:07', '2026-09-14 20:49:07'),
