INSERT INTO `testimonials` (`id`, `name`, `profession`, `content`, `photo`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Eva Astuti', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Anakku bernama Abdurrosyad Fadlillah saat ini duduk di kelas XI. Alhamdulillah sekarang sudah mulai berani tampil dan mandiri, sopan santun semakin baik. Semoga dengan bimbingan dari asatidz dan ustadzah di pondok, ananda semakin percaya diri, berakhlakul karimah, dan disiplin dalam ibadah maupun belajar. Aamiin ya Rabbal \'alamin.', NULL, 'publish', '2026-09-14 15:27:46', '2026-09-14 15:27:46'),
(2, 'Ayu Putri', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Toby Aldinata Timothy anakku santri baru tahun ini di Pondok Pesantren Raudhatul Ulum. Pembinaan karakternya sangat terasa sejak awal masuk. Semoga yang baik menjadi semakin baik lagi dan istiqomah.', NULL, 'publish', '2026-09-14 15:27:46', '2026-09-14 15:27:46'),
(3, 'Evi Riani', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Putri sulungku Seren Rahmadani saat ini duduk di kelas akhir. Alhamdulillah ada perubahan yang terus positif dan signifikan, hafalannya bertambah, mandiri, dan beradab sesuai nilai-nilai santri Raudhatul Ulum.', NULL, 'publish', '2026-09-14 15:27:46', '2026-09-14 15:27:46'),
(4, 'Penny Cahyani', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Najwa Rizkiya Ramadhani nama putriku yang saat ini duduk di kelas akhir. Kami sangat bersyukur menyekolahkannya di Pondok Pesantren Raudhatul Ulum Sakatiga. Semoga setelah lulus ananda bisa menjadi generasi berakhlak mulia yang bermanfaat bagi umat.', NULL, 'publish', '2026-09-14 15:27:46', '2026-09-14 15:27:46'),
(5, 'Yulianti Widiastuti', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Anakku bernama Annisa Dhiya Abelia saat ini sudah di kelas XII. Anak semakin percaya diri, hafalan Al-Qur\'annya terus bertambah mutqin, dan selalu berhati-hati serta berpegang teguh pada nilai-nilai agama dalam kesehariannya.', NULL, 'publish', '2026-09-14 15:27:46', '2026-09-14 15:27:46'),
(6, 'Dora Indah', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Anakku bernama Ragil Rizgy Putra duduk di kelas XI. Saya merasa membuat pilihan yang sangat tepat menitipkan anak di Pondok Pesantren Raudhatul Ulum Sakatiga. Kekeluargaan para asatidz dan pengasuh asrama membuat kami tenang, bersama membimbing anak-anak menuju sukses dunia dan akhirat. Aamiin.', NULL, 'publish', '2026-09-14 15:27:46', '2026-09-14 15:27:46'),
(7, 'Suharyanti', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Abi Anggara Santriyano adalah anak laki-lakiku yang saat ini duduk di kelas XII. PPRU terus mengutamakan kualitas pendidikan agama, tahfidz, dan akhlakul karimah. Para ustadz memberikan perhatian terbaik dan mendidik sepenuh hati.', NULL, 'publish', '2026-09-14 15:27:46', '2026-09-14 15:27:46'),
(8, 'Sugiarti', 'Alumni Pondok Pesantren Raudhatul Ulum', 'Setelah menempuh pendidikan di Pondok Pesantren Raudhatul Ulum, saya merasakan perubahan besar dalam hal kedisiplinan ibadah dan pergaulan. Ilmu agama dan wawasan yang didapat sangat mendalam, didukung lingkungan ukhuwah santri yang saling menyemangati dalam kebaikan.', NULL, 'publish', '2026-09-14 15:27:46', '2026-09-14 15:27:46'),
(9, 'Shella Destiani', 'Alumni Pondok Pesantren Raudhatul Ulum', 'Pondok Pesantren Raudhatul Ulum memiliki lingkungan yang sangat suportif, tanpa senioritas yang merugikan. Asatidz dan dewan guru sangat peduli, membimbing kami layaknya orang tua kedua. Bekal adab, Al-Qur\'an, dan kemandirian dari pondok menjadi modal berharga bagi saya saat melanjutkan pendidikan dan berkarier.', NULL, 'publish', '2026-09-14 15:27:46', '2026-09-14 15:27:46'),
(10, 'Toni Siswanto dan Widyaningtyastuti', 'Wali Santri Pondok Pesantren Raudhatul Ulum', 'Assalamu\'alaikum warahmatullahi wabarakatuh. Kami orang tua dari ananda Yunita Andini Amalia bersyukur ananda menuntut ilmu di Pondok Pesantren Raudhatul Ulum Sakatiga. Pondok mendidik santri dengan penuh kasih sayang, membekali dengan tahfidz, tahsin bersanad, bahasa Arab-Inggris, serta ilmu pengetahuan umum. Lingkungan asrama islami dan terjaga.', NULL, 'publish', '2026-09-14 15:27:46', '2026-09-14 15:27:46');
INSERT INTO `unit_pendidikans` (`id`, `name`, `short_name`, `slug`, `category_type`, `curriculum`, `badge`, `description`, `head_name`, `phone`, `email`, `website_url`, `thumbnail`, `icon`, `order`, `is_active`, `created_at`, `updated_at`, `logo`) VALUES
(1, 'Madrasah Aliyah Raudhatul Ulum', 'MARU', 'madrasah-aliyah-raudhatul-ulum', 'Madrasah', 'Kurikulum Terpadu Gontor & Kemenag / Muadalah Al-Azhar Kairo Mesir', 'Terakreditasi A & Muadalah Al-Azhar', 'Madrasah Aliyah (setara SMA) berasrama putra dan putri dengan kurikulum terpadu ilmu-ilmu syar\'i (Kitab Kuning), dwi-bahasa aktif (Arab & Inggris), serta sains umum. Lulusan MARU memiliki ijazah muadalah resmi yang diakui langsung di Universitas Al-Azhar Kairo Mesir dan Universitas Islam Madinah Arab Saudi.', 'Ustadz Fulan, S.Ag., M.Pd.I.', '0812-7890-1950', 'maru@ppru.ac.id', NULL, '/uploads/campus-ppru-sakatiga.webp', 'fa-solid fa-graduation-cap', 1, 1, '2026-09-14 15:27:45', '2026-09-15 18:43:40', '/uploads/logos/logo-maru.svg'),
(2, 'Madrasah Tsanawiyah Raudhatul Ulum', 'MATSARU', 'madrasah-tsanawiyah-raudhatul-ulum', 'Madrasah', 'Kurikulum Terpadu Gontor & Kemenag / Muadalah Al-Azhar', 'Terakreditasi A', 'Madrasah Tsanawiyah (setara SMP) berasrama yang fokus pada peletakan pondasi aqidah shohihah, pembiasaan ibadah yaumiyah, tahfidz, dan kemampuan dasar percakapan bahasa Arab & Inggris aktif.', 'Ustadz Fulan, Drs., M.Pd.I.', '0812-7890-1950', 'matsaru@ppru.ac.id', NULL, '/uploads/campus-robbani.webp', 'fa-solid fa-book-open-reader', 2, 1, '2026-09-14 15:27:45', '2026-09-15 18:43:40', '/uploads/logos/logo-matsaru.svg'),
(3, 'Madrasah Ibtidaiyah Raudhatul Ulum', 'MIRU', 'madrasah-ibtidaiyah-raudhatul-ulum', 'Madrasah', 'Kurikulum Kemenag & Muatan Lokal Kepesantrenan', 'Terakreditasi A', 'Pendidikan dasar Islam formal tingkat Ibtidaiyah (setara SD) dengan penekanan pada tartil Al-Qur\'an, pembiasaan akhlak terpuji, dan dasar-dasar ilmu umum yang kokoh sejak usia dini.', 'Ustadzah Fulanah, S.Pd.I.', '0812-7890-1950', 'miru@ppru.ac.id', NULL, '/uploads/activities-ppru-sakatiga.webp', 'fa-solid fa-school', 3, 1, '2026-09-14 15:27:45', '2026-09-15 18:43:40', '/uploads/logos/logo-miru.svg'),
(4, 'Madrasah Tahfizhul Qur\'an Lil Aulad', 'MATQULARU', 'madrasah-tahfizhul-quran-raudhatul-ulum', 'Madrasah', 'Kurikulum Khusus Tahfidz 30 Juz Mutqin Bersanad & Ulumul Qur\'an', 'Tahfidz Khusus Bersanad', 'Lembaga pendidikan khusus tahfidz Al-Qur\'an dengan metode intensif dan bimbingan masyaikh serta para huffazh bersanad untuk mencetak kader penghafal Al-Qur\'an 30 juz mutqin.', 'Ustadz Fulan, Al-Hafizh, S.Q.', '0812-7890-1950', 'tahfidz@ppru.ac.id', NULL, '/uploads/ppru-tahfidz.webp', 'fa-solid fa-book-quran', 4, 1, '2026-09-14 15:27:45', '2026-09-15 18:43:40', '/uploads/logos/logo-matqularu.svg'),
(5, 'Taman Kanak-Kanak Islam Raudhatul Ulum', 'TAKIRU', 'taman-kanak-kanak-islam-raudhatul-ulum', 'TK Islam', 'Pendidikan Anak Usia Dini Islami Terpadu & Sentra Qur\'ani', 'PAUD & TK Islam Terdaftar', 'Pendidikan anak usia dini yang menyenangkan dengan pendekatan sentra Qur\'ani, pembiasaan doa dan adab harian, motorik anak, serta keceriaan belajar dalam suasana islami.', 'Ustadzah Fulanah, S.Pd., M.Pd.', '0812-7890-1950', 'takiru@ppru.ac.id', NULL, '/uploads/units/ppru-gedung-utama-1789418946-TYobz.webp', 'fa-solid fa-shapes', 5, 1, '2026-09-14 15:27:45', '2026-09-15 18:43:40', '/uploads/logos/logo-takiru.svg'),
(6, 'SMP Islam Terpadu Raudhatul Ulum', 'SMPIT RU', 'smp-islam-terpadu-raudhatul-ulum', 'Sekolah IT', 'Kurikulum JSIT Indonesia & Kurikulum Nasional', 'Terakreditasi A - JSIT', 'Sekolah Menengah Pertama Islam Terpadu berasrama yang unggul dalam integrasi ilmu pengetahuan, pembinaan adab santri, kemandirian kepanduan pramuka, dan eksplorasi bakat minat siswa.', 'Ustadz Fulan, S.Pd.I., M.Pd.', '0812-7890-1950', 'smpit@ppru.ac.id', NULL, '/uploads/lab-robbani.webp', 'fa-solid fa-award', 6, 1, '2026-09-14 15:27:45', '2026-09-15 18:43:40', '/uploads/logos/logo-smpit.svg'),
(7, 'SMA Islam Terpadu Raudhatul Ulum', 'SMAIT RU', 'sma-islam-terpadu-raudhatul-ulum', 'Sekolah IT', 'Kurikulum JSIT Indonesia & Kurikulum Merdeka Nasional', 'Terakreditasi B - JSIT', 'Sekolah Menengah Atas berbasis Islam Terpadu yang memadukan keunggulan sains teknologi, pembinaan karakter kepemimpinan, riset ilmiah remaja, dan tahfidzul qur\'an mutqin.', 'Ustadz Fulan, M.Pd.', '0812-7890-1950', 'smait@ppru.ac.id', NULL, '/uploads/library-robbani.webp', 'fa-solid fa-atom', 7, 1, '2026-09-14 15:27:45', '2026-09-15 18:43:40', '/uploads/logos/logo-smait.svg'),
(8, 'Institut Agama Islam Nur Raudhatul Ulum', 'IAI NRU', 'institut-agama-islam-nur-raudhatul-ulum', 'Perguruan Tinggi', 'Kurikulum Pendidikan Tinggi Islam Kemenag RI (S1 PAI & Perbankan Syariah)', 'Terakreditasi BAN-PT', 'Institut Agama Islam di lingkungan pesantren menyelenggarakan program Sarjana (S1) dengan keunggulan integrasi ilmu syar\'i, riset ilmiah, dan kepemimpinan dakwah.', 'Dr. Ustadz Fulan, M.A.', '0812-7890-1950', 'iainru@ppru.ac.id', NULL, '/uploads/units/ppru-gedung-utama-1789418946-f318v.webp', 'fa-solid fa-graduation-cap', 8, 1, '2026-09-14 15:27:45', '2026-09-15 18:43:40', '/uploads/logos/logo-iainru.svg');
